// --- Prompt syntax parser ---
// Pure (no figma API): it runs both in the plugin code and inside the palette
// window (inlined by generate.js), and test/parse.test.js loads it into a vm.

const KIND_LABEL = { padding: "Padding", gap: "Gap", radius: "Radius", fill: "Fill", stroke: "Border", textstyle: "Text", component: "Insert" };
const SIDE_LABEL = {
  ALL: "", H: " horizontal", V: " vertical", T: " top", B: " bottom", L: " left", R: " right",
  TL: " top-left", TR: " top-right", BL: " bottom-left", BR: " bottom-right",
  COL: " columns", ROW: " rows",
};

// Op key -> [kind, side]. Sides map to fields via FIELD_SETS in runtime.js.
const SIDE_OPS = {
  p: ["padding", "ALL"], ph: ["padding", "H"], pv: ["padding", "V"],
  pt: ["padding", "T"], pb: ["padding", "B"], pl: ["padding", "L"], pr: ["padding", "R"],
  g: ["gap", "ALL"], gc: ["gap", "COL"], gr: ["gap", "ROW"],
  r: ["radius", "ALL"], rt: ["radius", "T"], rb: ["radius", "B"], rl: ["radius", "L"], rr: ["radius", "R"],
  rtl: ["radius", "TL"], rtr: ["radius", "TR"], rbl: ["radius", "BL"], rbr: ["radius", "BR"],
};
const FUZZY_OPS = { f: "fill", b: "stroke", t: "textstyle" };

// Ops that are a single word with no value or token behind them (no slug).
const WORD_OPS = {
  frame: { kind: "frame", label: "Insert frame" },
  alh: { kind: "autolayout", value: "HORIZONTAL", label: "Auto layout horizontal" },
  alv: { kind: "autolayout", value: "VERTICAL", label: "Auto layout vertical" },
};


// What a bare word like "button" or "brand" searches, in tie-break order. Not
// stroke: it has the same names as fill, so a bare color name means fill.
const SEARCH_KINDS = ["component", "textstyle", "fill"];

// Palette groups. `prefix` turns input typed inside a group into full syntax
// ("m" in Padding is "p m", "brand" in Fill is "f brand"). `search` limits name
// search inside the group instead (components have no op key).
const GROUPS = [
  { kind: "padding", label: "Padding", key: "p", prefix: "p " },
  { kind: "gap", label: "Gap", key: "g", prefix: "g " },
  { kind: "radius", label: "Radius", key: "r", prefix: "r " },
  { kind: "fill", label: "Fill", key: "f", prefix: "f " },
  { kind: "stroke", label: "Border", key: "b", prefix: "b " },
  { kind: "textstyle", label: "Text", key: "t", prefix: "t " },
  { kind: "component", label: "Component", prefix: "", search: ["component"] },
  { kind: "layout", label: "Layout", key: "al", prefix: "al" },
];

const ALIAS_NAME = /^[a-z0-9][a-z0-9-]*$/;

// Icon font styles share sizes with real text styles; rank them last in fuzzy matches.
const DEMOTED = /\/font awesome\//i;

// The help view's Guide tab: sections of [examples, meaning]. Every example is
// clickable and must parse. Keep in sync with parse() and the README table.
const SYNTAX = [
  {
    title: "Spacing and radius",
    rows: [
      [["p m", "p 12"], "Padding M (12px) on all sides; adds auto layout to a frame without it"],
      [["ph l", "pv s"], "Padding horizontal or vertical"],
      [["pt m", "pb m", "pl m", "pr m"], "Padding on one side"],
      [["g s", "g auto"], "Gap S, or auto (space between); also adds auto layout when needed"],
      [["gc s", "gr m"], "Grid column or row gap, on frames with grid layout"],
      [["r l", "r full"], "Radius on all corners"],
      [["rt m", "rtl s"], "Radius on two corners or one corner"],
    ],
  },
  {
    title: "Colors and text",
    rows: [
      [["f brand", "f base1", "f base-1"], "Fill, matched by color name (dashes optional)"],
      [["b brand", "b basedimmed3", "b base-dimmed-3"], "Border, 1px on all sides, matched by color name"],
      [["h1", "h3", "t regular"], "Text style: changes selected text, or inserts a new text layer"],
    ],
  },
  {
    title: "Frames and auto layout",
    rows: [
      [["frame"], "Insert a frame; ops after it apply to the new frame"],
      [["alh", "alv"], "Auto layout horizontal or vertical"],
      [["frame alh p m r m"], "Build a styled frame in one go"],
    ],
  },
  {
    title: "Components",
    rows: [
      [["button", "basic input"], "Search components, text styles and colors by name"],
      [["box r m"], "Insert, then style the new instance"],
    ],
  },
  {
    title: "Combine",
    rows: [[["p m g s r l"], "Several at once: each property, a space, then its value"]],
  },
];

// Dashes and other separators are optional when comparing with the last segment
// ("base3" matches "bfc-base-3").
// 0 = a path segment equals the query, 1 = last segment starts with it,
// 2 = contains it, or every query word starts a word in the name, in any order
// ("icon button" -> "Button (icon only)", but not "box rm" -> "Checkbox-indeteRMinate"),
// 3 = subsequence within one path segment, starting at a word start ("btn" ->
// "Button", but not "modal" -> "M/Open sans/semibold itALic"), -1 = no match.
function matchScore(name, q) {
  const n = name.toLowerCase();
  const segs = n.split("/");
  const last = segs[segs.length - 1].replace(/^bfc-/, "");
  const compact = (s) => s.replace(/[^a-z0-9]/g, "");
  if (segs.includes(q) || (compact(q) && compact(last) === compact(q))) return 0;
  if (last.startsWith(q) || compact(last).startsWith(compact(q))) return 1;
  if (n.includes(q)) return 2;
  const words = q.split(" ");
  const nameWords = n.split(/[^a-z0-9]+/);
  if (words.length > 1 && words.every((w) => nameWords.some((nw) => nw.startsWith(w)))) return 2;
  for (const seg of segs) {
    for (let start = 0; start < seg.length; start++) {
      if (seg[start] !== q[0] || (start > 0 && !/[\s(.-]/.test(seg[start - 1]))) continue;
      let i = 0;
      for (const ch of seg.slice(start)) if (ch === q[i]) i++;
      if (i === q.length) return 3;
    }
  }
  return -1;
}

// options.search = false turns off name search for bare words, leaving only
// op syntax (used to check alias names against built-in syntax); an array
// limits it to those kinds (the Component group).
// options.limit caps fuzzy matches per slot (default 12).
function createParser(entries, aliases, options) {
  const search = !options || options.search !== false;
  const searchKinds = (options && Array.isArray(options.search) && options.search) || SEARCH_KINDS;
  const limit = (options && options.limit) || 12;
  const bySlug = {};
  for (const e of entries) bySlug[e.slug] = e;
  const kindCache = {};
  const byKind = (kind) => kindCache[kind] || (kindCache[kind] = entries.filter((e) => e.kind === kind));
  // A size by name ("m") or by its number ("12", "12px"; `px` from generate.js).
  const valueEntry = (kind, v) => {
    const px = /^\d+(\.\d+)?(px)?$/.test(v) ? parseFloat(v) : null;
    return byKind(kind).find((e) => e.name.toLowerCase() === v) || (px !== null ? byKind(kind).find((e) => e.px === px) : undefined);
  };
  const startsValue = (e, v) => e.name.toLowerCase().startsWith(v) || (e.px !== undefined && String(e.px).startsWith(v));

  // `at` is [from, to): the typed words an op came from, so the palette can
  // box them. Ops built outside parse (lists, shorthand) have none.
  function sideOp(key, entry, at) {
    const [kind, side] = SIDE_OPS[key];
    return { slug: entry.slug, kind, side, key, label: KIND_LABEL[kind] + SIDE_LABEL[side] + " " + entry.name, at };
  }
  function nameOp(entry, at) {
    return { slug: entry.slug, kind: entry.kind, label: KIND_LABEL[entry.kind] + " " + entry.name, at };
  }
  const wordOp = (w, at) => Object.assign({ key: w, at }, WORD_OPS[w]);
  // "g auto": space between, so the gap follows the frame. No token behind it.
  const autoGapOp = (at) => ({ kind: "gap", side: "ALL", key: "g", value: "auto", label: "Gap auto", at });
  // Every value a side op can take, as ops: its sizes, plus auto for plain gap.
  const sideValues = (key, at) => byKind(SIDE_OPS[key][0]).map((x) => sideOp(key, x, at)).concat(key === "g" ? [autoGapOp(at)] : []);
  const startsSideValue = (op, v) => (op.value === "auto" ? "auto".startsWith(v) : startsValue(bySlug[op.slug], v));

  function fuzzy(kinds, q, limit) {
    return kinds
      .flatMap(byKind)
      .map((e) => [e, matchScore(e.name, q)])
      .filter(([, s]) => s >= 0)
      .sort(
        (a, b) =>
          a[1] - b[1] ||
          DEMOTED.test(a[0].name) - DEMOTED.test(b[0].name) ||
          kinds.indexOf(a[0].kind) - kinds.indexOf(b[0].kind) ||
          a[0].name.length - b[0].name.length
      )
      .slice(0, limit)
      .map(([e]) => e);
  }

  function fuzzySlot(ops, kinds, q, at) {
    const m = fuzzy(kinds, q, limit);
    if (!m.length) return { error: "No " + (kinds.length > 1 ? "" : KIND_LABEL[kinds[0]].toLowerCase() + " ") + 'matches "' + q + '"' };
    if (!q) return { primary: null, alternatives: m.map((e) => ops.concat(nameOp(e, at))) };
    return { primary: ops.concat(nameOp(m[0], at)), alternatives: m.slice(1).map((e) => ops.concat(nameOp(e, at))) };
  }

  const isKeyword = (w) => Boolean(SIDE_OPS[w] || FUZZY_OPS[w] || WORD_OPS[w] || aliases[w]);
  const bestScore = (kinds, q) =>
    kinds.flatMap(byKind).reduce((best, e) => {
      const s = matchScore(e.name, q);
      return s >= 0 && (best < 0 || s < best) ? s : best;
    }, -1);
  const isStrongName = (w) => {
    const s = bestScore(SEARCH_KINDS, w);
    return s >= 0 && s <= 2;
  };

  // The spaced form of a word in the old glued syntax ("pm" -> "p m",
  // "rtll" -> "rtl l", "fbrand" -> "f brand"), or null. A glued color only
  // counts when the whole word isn't a good name itself ("brand", "button").
  function splitGlued(w) {
    const side = Object.keys(SIDE_OPS).find((k) => w.length > k.length && w.startsWith(k) && valueEntry(SIDE_OPS[k][0], w.slice(k.length)));
    if (side) return side + " " + w.slice(side.length);
    const key = Object.keys(FUZZY_OPS).find((k) => w.length > k.length && w.startsWith(k) && fuzzy([FUZZY_OPS[k]], w.slice(k.length), 1).length);
    return key && !isStrongName(w) ? key + " " + w.slice(key.length) : null;
  }

  // Returns { primary: ops | null, alternatives: ops[] } or { error }.
  // primary is how the whole input is understood; alternatives are other
  // readings or completions of the last word.
  function parse(query) {
    const words = query.trim().split(/\s+/).filter(Boolean);
    // Where each word was typed: words from an alias all point at the alias.
    const src = words.map((_, i) => i);
    const at = (from, to) => [src[from], src[to - 1] + 1];
    const ops = [];
    // Aliases only expand where an op can start, never where a value is
    // expected, so an alias named "m" or "brand" can't break "p m" or "f brand".
    // Words that came from an alias (up to aliasEnd) aren't expanded again.
    let aliasEnd = -1;
    words: for (let i = 0; i < words.length; i++) {
      const alias = i > aliasEnd && aliases[words[i].toLowerCase()];
      if (alias) {
        const parts = alias.trim().split(/\s+/);
        words.splice(i, 1, ...parts);
        src.splice(i, 1, ...parts.map(() => src[i]));
        aliasEnd = i + parts.length - 1;
        i--;
        continue;
      }
      const w = words[i].toLowerCase();
      const isLast = i === words.length - 1;

      if (FUZZY_OPS[w]) {
        const kind = FUZZY_OPS[w];
        if (isLast) return fuzzySlot(ops, [kind], "", at(i, i + 1));
        const q = words[++i].toLowerCase();
        if (i === words.length - 1) return fuzzySlot(ops, [kind], q, at(i - 1, i + 1));
        const best = fuzzy([kind], q, 1)[0];
        if (!best) return { error: "No " + KIND_LABEL[kind].toLowerCase() + ' matches "' + q + '"' };
        ops.push(nameOp(best, at(i - 1, i + 1)));
        continue;
      }

      if (/^h[1-5]$/.test(w) && valueEntry("textstyle", w)) {
        ops.push(nameOp(valueEntry("textstyle", w), at(i, i + 1)));
        continue;
      }

      if (WORD_OPS[w]) {
        ops.push(wordOp(w, at(i, i + 1)));
        continue;
      }
      // Typing a word op ("fr", "al"): offer it before other readings like f + "r".
      const wordCompletions = isLast ? Object.keys(WORD_OPS).filter((k) => k.startsWith(w)) : [];
      if (wordCompletions.length) return { primary: null, alternatives: wordCompletions.map((k) => ops.concat(wordOp(k, at(i, i + 1)))) };

      // A property and its value are two words: "p m", "pl m", "rtl s", "r 12", "g auto".
      if (SIDE_OPS[w]) {
        const kind = SIDE_OPS[w][0];
        if (isLast) return { primary: null, alternatives: sideValues(w, at(i, i + 1)).map((op) => ops.concat(op)) };
        const next = words[i + 1].toLowerCase();
        const e = valueEntry(kind, next);
        if (e || (w === "g" && next === "auto")) {
          ops.push(e ? sideOp(w, e, at(i, i + 2)) : autoGapOp(at(i, i + 2)));
          i++;
          continue;
        }
        const opts = i + 1 === words.length - 1 ? sideValues(w, at(i, i + 2)).filter((op) => startsSideValue(op, next)) : [];
        if (opts.length) return { primary: null, alternatives: opts.map((op) => ops.concat(op)) };
        return { error: KIND_LABEL[kind] + ' has no size "' + words[i + 1] + '"' };
      }

      const typingAlias = isLast && Object.keys(aliases).some((a) => a.startsWith(w));
      const spaced = !typingAlias && splitGlued(w);
      if (spaced) return { error: 'Put a space after the property: "' + spaced + '"' };

      // Anything else is a name search over components, text styles and colors.
      // The longest run of words that matches a name wins, as long as what
      // follows still parses: "icon button" is one name, "basic input p m" is
      // Basic input · Padding M.
      if (search) {
        // A name never runs into an op keyword or an alias, so
        // "button b brand" is Button · Border, not a search for "button b".
        let end = i + 1;
        while (end < words.length && !isKeyword(words[end].toLowerCase())) end++;
        for (let j = end; j > i + 1; j--) {
          const name = words.slice(i, j).join(" ").toLowerCase();
          const match = fuzzy(searchKinds, name, 1)[0];
          if (!match) continue;
          if (j === words.length) return fuzzySlot(ops, searchKinds, name, at(i, j));
          if (parse(words.slice(j).join(" ")).error) continue;
          ops.push(nameOp(match, at(i, j)));
          i = j - 1;
          continue words;
        }
      }
      const found = search && w.length >= 2 ? fuzzy(searchKinds, w, limit) : [];
      if (!isLast && found.length) {
        ops.push(nameOp(found[0], at(i, i + 1)));
        continue;
      }
      if (!isLast) return { error: 'No matches for "' + words[i] + '". Type ? for help' };

      // Still typing the last word: alias completions come first, then name matches.
      const aliasOpts = Object.keys(aliases)
        .filter((a) => a.startsWith(w))
        .map((a) => {
          const r = parse(words.slice(0, i).concat(a).join(" ")).primary;
          return r && ops.concat(r.slice(ops.length).map((o) => Object.assign({}, o, { at: at(i, i + 1) })));
        })
        .filter(Boolean);
      const named = found.map((e) => ops.concat(nameOp(e, at(i, i + 1))));
      if (!aliasOpts.length && named.length) return { primary: named[0], alternatives: named.slice(1) };
      if (aliasOpts.length) return { primary: null, alternatives: aliasOpts.concat(named) };
      return { error: 'No matches for "' + words[i] + '". Type ? for help' };
    }
    return { primary: ops.length ? ops : null, alternatives: [] };
  }

  // The shortest built-in input for these ops ("p m g s", "f base3"), or null
  // if some op has none (components and most text styles are searched by name,
  // and a color only gets one if its compact name is unique). Cached: the Fill
  // group asks for hundreds at once.
  const shorthandCache = new Map();
  const COLOR_KEYS = { fill: "f", stroke: "b" };
  function shorthand(ops) {
    const cacheKey = ops.map((o) => (o.slug || o.key) + ":" + (o.side || "")).join(",");
    if (!shorthandCache.has(cacheKey)) shorthandCache.set(cacheKey, computeShorthand(ops));
    return shorthandCache.get(cacheKey);
  }
  // "f base3" for Base/bfc-base-3: the key plus the compact last segment, if that
  // gives exactly this color when parsed. Checked from a per-kind index instead
  // of a full parse per row, which took close to a second for all fills.
  const compactLast = (name) => name.toLowerCase().split("/").pop().replace(/^bfc-/, "").replace(/[^a-z0-9]/g, "");
  const colorIndex = {};
  function colorShorthand(kind, entry) {
    if (!colorIndex[kind]) {
      const counts = {};
      const segs = new Set();
      for (const e of byKind(kind)) {
        counts[compactLast(e.name)] = (counts[compactLast(e.name)] || 0) + 1;
        for (const seg of e.name.toLowerCase().split("/")) segs.add(seg);
      }
      colorIndex[kind] = { counts, segs };
    }
    const c = compactLast(entry.name);
    const { counts, segs } = colorIndex[kind];
    // Another color with the same compact name.
    if (!c || counts[c] !== 1) return null;
    const word = COLOR_KEYS[kind] + " " + c;
    // A path segment equal to it ("brand" in Pop/Brand) makes ranking decide: parse to be sure.
    if (segs.has(c)) {
      const r = parse(word).primary;
      return r && r.length === 1 && r[0].slug === entry.slug ? word : null;
    }
    return word;
  }

  function computeShorthand(ops) {
    const parts = [];
    for (const op of ops) {
      if (WORD_OPS[op.key] || op.value === "auto") {
        parts.push(op.value === "auto" ? "g auto" : op.key);
        continue;
      }
      if (!bySlug[op.slug]) return null;
      const name = bySlug[op.slug].name.toLowerCase();
      if (op.key) {
        parts.push(op.key + " " + name);
      } else if (op.kind === "textstyle" && /^h[1-5]$/.test(name)) {
        parts.push(name);
      } else if (COLOR_KEYS[op.kind]) {
        const word = colorShorthand(op.kind, bySlug[op.slug]);
        if (!word) return null;
        parts.push(word);
      } else {
        return null;
      }
    }
    return parts.join(" ");
  }

  // Every entry of a kind as a one-op list (all sides/corners for spacing and radius).
  function list(kind) {
    if (kind === "layout") return Object.keys(WORD_OPS).map((k) => [wordOp(k)]);
    if (kind === "gap") return sideValues("g").map((op) => [op]);
    const key = { padding: "p", radius: "r" }[kind];
    return byKind(kind).map((e) => [key ? sideOp(key, e) : nameOp(e)]);
  }

  return { parse, shorthand, list, splitGlued };
}

// Aliases saved before a space was required ("pm gs") are rewritten with
// spaces ("p m g s"). Returns the expansion unchanged if it already parses,
// or null if the rewrite doesn't parse either.
function respaceAlias(entries, expansion) {
  const parser = createParser(entries, {});
  if (!parser.parse(expansion).error) return expansion;
  const words = expansion.trim().split(/\s+/);
  const fixed = words.map((w) => parser.splitGlued(w.toLowerCase()) || w).join(" ");
  return parser.parse(fixed).primary ? fixed : null;
}

// The Options tree: kinds, then the entry's group (a fill's collection, a
// component's page), then its name path. A group with a single child is merged
// into it, so there are no one-item levels to click through. Every node has
// `slugs`: all leaf slugs below it, for toggling a whole group at once.
function buildOptionTree(entries) {
  const root = { id: "", label: "All options", children: [] };
  const groupNode = (parent, label) => {
    let node = parent.children.find((c) => c.children && c.label === label);
    if (!node) parent.children.push((node = { id: parent.id + "/" + label, label, children: [] }));
    return node;
  };
  for (const g of GROUPS) {
    const kindNode = { id: g.kind, label: g.label, children: [] };
    for (const e of entries) {
      if (e.kind !== g.kind) continue;
      let parts = e.name.split("/");
      if (e.kind === "component") parts = [e.name.startsWith(e.group + "/") ? e.name.slice(e.group.length + 1) : e.name];
      if (e.group) parts = [e.group].concat(parts);
      let node = kindNode;
      for (const seg of parts.slice(0, -1)) node = groupNode(node, seg);
      node.children.push({ id: e.slug, label: parts[parts.length - 1], slug: e.slug });
    }
    if (kindNode.children.length) root.children.push(kindNode);
  }
  const finish = (node, isKind) => {
    if (!node.children) {
      node.slugs = [node.slug];
      return node;
    }
    node.children = node.children.map((c) => finish(c, false));
    if (!isKind && node.children.length === 1) {
      const only = node.children[0];
      const label = only.label === node.label ? node.label : node.label + "/" + only.label;
      return Object.assign({}, only, { label });
    }
    node.slugs = node.children.flatMap((c) => c.slugs);
    return node;
  };
  root.children = root.children.map((c) => finish(c, true));
  root.slugs = root.children.flatMap((c) => c.slugs);
  return root;
}

// --- Availability: which ops can do something to which layers ---
// Layers are described by capabilities (nodeCaps in runtime.js): which properties
// an op needs for it to have a visible effect. The palette hides ops that would
// do nothing, and the plugin applies an op only to layers that support it, so
// both sides must use opSupports and checkOps below.

// Capabilities of layers created by inserts. A component's instance is assumed
// to be auto layout: what's inside isn't known until it's imported.
const INSERTED_CAPS = {
  frame: { fills: true, strokes: true, radius: true, corners: true, autoLayout: false, canAutoLayout: true, text: false },
  component: { fills: true, strokes: true, radius: true, corners: true, autoLayout: true, canAutoLayout: false, text: false },
  textstyle: { fills: true, strokes: true, radius: false, corners: false, autoLayout: false, canAutoLayout: false, text: true },
};

function opNeed(op) {
  if (op.kind === "gap" && (op.side === "COL" || op.side === "ROW")) return "grid";
  if (op.kind === "gap" && op.value === "auto") return "flow";
  if (op.kind === "padding" || op.kind === "gap") return "frame";
  if (op.kind === "radius") return op.side === "ALL" ? "radius" : "corners";
  if (op.kind === "fill") return "fills";
  if (op.kind === "stroke") return "strokes";
  if (op.kind === "autolayout") return "canAutoLayout";
  if (op.kind === "textstyle") return "text";
  return null;
}

const NEED_MESSAGE = {
  frame: "needs a frame",
  radius: "needs a frame or shape with corner radius",
  corners: "needs a frame or rectangle with individual corners",
  fills: "needs a layer that can have a fill",
  strokes: "needs a layer that can have a border",
  canAutoLayout: "needs a frame (instances get auto layout from their component)",
  grid: "needs a frame with grid layout",
  flow: "needs a frame without grid layout",
};

// Padding and gap add auto layout to a frame that has none (applyOp in runtime.js).
// Gap auto is space-between, which grid layout doesn't have.
function opSupports(caps, op) {
  const need = opNeed(op);
  if (need === "frame") return Boolean(caps.autoLayout || caps.canAutoLayout);
  if (need === "flow") return Boolean(caps.autoLayout || caps.canAutoLayout) && !caps.grid;
  return !need || Boolean(caps[need]);
}

// Walks the ops in order against the selected layers' capabilities, the same way
// applyOps applies them: inserts (frame, component, and a text style when no
// text is selected) replace the targets with the new layer, and alh/alv,
// padding and gap make frames auto layout. Returns { modes } per op ("insert",
// "apply", or "autolayout" for padding or gap that adds auto layout), or
// { error, index } for the first op that would do nothing.
function checkOps(ops, selection) {
  let targets = selection;
  const modes = [];
  for (let i = 0; i < ops.length; i++) {
    const op = ops[i];
    const inserts = op.kind === "frame" || op.kind === "component" || (op.kind === "textstyle" && !targets.some((t) => t.text));
    if (inserts) {
      targets = [INSERTED_CAPS[op.kind]];
      modes.push("insert");
      continue;
    }
    if (!targets.some((t) => opSupports(t, op))) {
      const error = targets.length ? opLabel(op, "apply") + " " + NEED_MESSAGE[opNeed(op)] : "Select a layer first";
      return { error, index: i };
    }
    const addsLayout = (opNeed(op) === "frame" || opNeed(op) === "flow") && targets.some((t) => !t.autoLayout && t.canAutoLayout);
    if (op.kind === "autolayout" || addsLayout) targets = targets.map((t) => (t.canAutoLayout ? Object.assign({}, t, { autoLayout: true }) : t));
    modes.push(addsLayout ? "autolayout" : "apply");
  }
  return { modes };
}

// A text style inserts a new text layer when no text is selected, and padding
// or gap on a frame without auto layout adds it.
function opLabel(op, mode) {
  if (op.kind === "textstyle" && mode === "insert") return "Insert text " + op.label.replace(/^Text /, "");
  if (mode === "autolayout") return op.label + " (adds auto layout)";
  return op.label;
}
function describeOpsIn(ops, modes) {
  return ops.map((op, i) => opLabel(op, modes && modes[i])).join(" · ");
}

// Returns an error message, or null if the alias can be saved.
function aliasError(entries, name, expansion) {
  if (!ALIAS_NAME.test(name)) return "Alias names are lowercase letters, digits and -, not starting with -";
  const r0 = createParser(entries, {}, { search: false }).parse(name);
  if (!r0.error) return '"' + name + '" is already built-in syntax';
  const r = createParser(entries, {}).parse(expansion);
  if (r.error) return r.error;
  if (!r.primary) return "Incomplete: " + expansion;
  return null;
}

// A variable's value for the given modes ({ collection name: mode name }, from
// the selected layer), following aliases into other collections with their own
// mode. Collections the layer has no mode for use their default mode. table is
// VARIABLE_VALUES: id -> { collection, defaultMode, values: { mode: value } },
// or just the value for a variable with a single mode.
function resolveValue(table, id, modes) {
  for (let depth = 0; depth < 10; depth++) {
    const t = table[id];
    if (t === undefined || t === null) return null;
    if (typeof t !== "object") return t;
    const chosen = modes && modes[t.collection];
    const value = t.values[chosen in t.values ? chosen : t.defaultMode];
    if (value === undefined || value === null) return null;
    if (typeof value !== "object") return value;
    id = value.alias;
  }
  return null;
}

// "12px" for numbers, colors as they are ("#1A73E8").
function formatValue(value) {
  if (typeof value === "number") return Number(value.toFixed(2)) + "px";
  return typeof value === "string" ? value : null;
}

// ---------- Variable review ----------

// Colors the review proposes: the Mode collection, which follows Light/Dark.
// Not primitives (what those tokens point to), and not theme or effect
// tokens, which are picked on purpose.
const reviewColor = (e) => e.group === "Mode" && !/theme/i.test(e.name) && !e.name.startsWith("Effect variables/");
// Content colors, for text and icons: bfc-base-c-1, bfc-alert-c, and the
// high-contrast text on a Pop color, bfc-brand-hc.
const isContentColor = (e) => /-h?c(-|$)/.test(e.name.split("/").pop());
const COLOR_FAMILIES = ["Base", "Pop", "Miscellaneous"];

// The token to propose for a value set by hand: a number for padding, gap and
// radius, or "#RRGGBB(AA)" for fill and stroke, compared in the layer's modes.
// It's the token with that value (exact), or else the closest one. Ties: the
// larger size (3 between XXS 2 and XS 4 is XS); for colors, which share hexes
// a lot (white is nine tokens), the one for the layer's role: content colors
// for text (role "text"), background colors for anything else, Base before
// Pop, Neutral before other Pop colors. Text only ever gets content or Pop
// colors, never a Base background color, even if one is closer.
// Returns { match: slug | null, exact }.
function reviewChoices(entries, table, kind, value, modes, role) {
  const own = entries.filter((e) => e.kind === kind);
  if (typeof value === "number") {
    const best = own.filter((e) => e.px !== undefined).sort((a, b) => Math.abs(a.px - value) - Math.abs(b.px - value) || b.px - a.px)[0];
    return best ? { match: best.slug, exact: best.px === value } : { match: null, exact: false };
  }
  const forRole = (e) => isContentColor(e) === (role === "text");
  const family = (e) => {
    const i = COLOR_FAMILIES.indexOf(e.name.split("/")[0]);
    return i < 0 ? COLOR_FAMILIES.length : i;
  };
  const allowed = (e) => role !== "text" || isContentColor(e) || e.name.startsWith("Pop/");
  const neutral = (e) => e.name.startsWith("Pop/Neutral/");
  const best = own
    .filter((e) => reviewColor(e) && allowed(e))
    .map((e) => [e, colorDistance(resolveValue(table, e.id, modes), value)])
    .filter(([, d]) => d !== null)
    .sort((a, b) => a[1] - b[1] || forRole(b[0]) - forRole(a[0]) || family(a[0]) - family(b[0]) || neutral(b[0]) - neutral(a[0]) || a[0].name.length - b[0].name.length)[0];
  return best ? { match: best[0].slug, exact: best[1] === 0 } : { match: null, exact: false };
}

// "Padding 11px", "Text color #007375": a review group as the palette and the
// canvas highlight show it.
function reviewLabel(group) {
  return (group.role === "text" ? "Text color" : KIND_LABEL[group.kind]) + " " + formatValue(group.value);
}

// Distance between two "#RRGGBB(AA)" colors, alpha included; null if either
// isn't one.
function colorDistance(a, b) {
  const rgba = (hex) => {
    const m = typeof hex === "string" && /^#([0-9a-f]{6})([0-9a-f]{2})?$/i.exec(hex);
    if (!m) return null;
    const n = parseInt(m[1], 16);
    return [n >> 16, (n >> 8) & 255, n & 255, m[2] ? parseInt(m[2], 16) : 255];
  };
  const x = rgba(a);
  const y = rgba(b);
  return x && y ? Math.hypot(...x.map((v, i) => v - y[i])) : null;
}

// The Alias N menu commands run the alias named N without the palette.
function aliasOps(entries, aliases, name) {
  if (!aliases[name]) return { error: 'No alias "' + name + '". Add one in the palette: ? › Aliases' };
  const r = createParser(entries, aliases).parse(name);
  if (!r.primary) return { error: "Alias " + name + ": " + (r.error || "incomplete") };
  return { ops: r.primary };
}

function describeOps(ops) {
  return ops.map((o) => o.label).join(" · ");
}

// --- Runtime ---
// "Open palette" opens the palette window (UI_HTML). Parsing happens inside the
// window for instant feedback; this side applies ops and owns storage.
// "Alias N" runs alias N headless (runAlias); "Fix variables" binds the
// review's proposals headless (runFix).
//
// UI -> code: ready | apply {ops, keepOpen} | saveAlias {name, expansion} |
//             deleteAlias {name} | clearRecents | setHidden {hidden} | import {json} |
//             resize {width, height, save} | review | fixReview {fixes: [{key, slug}]} |
//             preview {keys, width, height} (show these review groups in the palette) |
//             vars | close
// code -> UI: init {entries, values, aliases, recents, hidden, selection} | selection {selection} |
//             (selection = {count, nodes: distinct nodeCaps of the selected layers,
//              modes: {collection name: mode name} of the first selected layer})
//             state {aliases, recents, hidden, error, notice} |
//             review {groups: [{key, kind, value, modes, role, layers, match, exact}], layers, errors} |
//             changed (the document changed; an open review scans again) |
//             preview {keys, imageId, image?, origin, focus, marks, elsewhere} or {keys, empty}

const ENTRIES = Object.keys(VARIABLE_MAP).map((slug) => Object.assign({ slug }, VARIABLE_MAP[slug]));
const MAX_RECENTS = 8;
const DEFAULT_SIZE = { width: 520, height: 600 };
const MIN_SIZE = { width: 380, height: 360 };

const FIELD_SETS = {
  padding: {
    T: ["paddingTop"],
    B: ["paddingBottom"],
    L: ["paddingLeft"],
    R: ["paddingRight"],
    H: ["paddingLeft", "paddingRight"],
    V: ["paddingTop", "paddingBottom"],
    ALL: ["paddingTop", "paddingBottom", "paddingLeft", "paddingRight"],
  },
  radius: {
    TL: ["topLeftRadius"],
    TR: ["topRightRadius"],
    BL: ["bottomLeftRadius"],
    BR: ["bottomRightRadius"],
    T: ["topLeftRadius", "topRightRadius"],
    B: ["bottomLeftRadius", "bottomRightRadius"],
    L: ["topLeftRadius", "bottomLeftRadius"],
    R: ["topRightRadius", "bottomRightRadius"],
    ALL: ["topLeftRadius", "topRightRadius", "bottomLeftRadius", "bottomRightRadius"],
  },
  gap: { ALL: ["itemSpacing", "counterAxisSpacing"], COL: ["gridColumnGap"], ROW: ["gridRowGap"] },
};

// Aliases ({ name: expansion }), recents ([{ ops, label }]) and hidden options
// (slugs the user turned off in the Options tab) live in clientStorage: per user
// and per machine, not synced. The help view can export/import aliases and hidden.
const state = { aliases: {}, recents: [], hidden: [], size: DEFAULT_SIZE };
const stateReady = Promise.all([
  figma.clientStorage.getAsync("aliases"),
  figma.clientStorage.getAsync("recents"),
  figma.clientStorage.getAsync("hidden"),
  figma.clientStorage.getAsync("size"),
]).then(([aliases, recents, hidden, size]) => {
  state.aliases = respaceAliases(aliases || {});
  if (aliases && JSON.stringify(state.aliases) !== JSON.stringify(aliases)) figma.clientStorage.setAsync("aliases", state.aliases);
  state.recents = recents || [];
  state.size = size || DEFAULT_SIZE;
  // Drop slugs that are no longer generated (e.g. after a library update), so
  // the "N hidden" count stays right.
  state.hidden = (hidden || []).filter((slug) => VARIABLE_MAP[slug]);
});

// Old glued expansions ("pm gs") get spaces ("p m g s"); ones that can't be
// fixed are kept, so the Aliases tab still shows them with their error.
function respaceAliases(aliases) {
  const out = {};
  for (const name of Object.keys(aliases)) out[name] = respaceAlias(ENTRIES, String(aliases[name])) || String(aliases[name]);
  return out;
}

// The Figma Plugin API has no built-in figma.clone(), so we make our own.
function clone(value) {
  return JSON.parse(JSON.stringify(value));
}

// ---------- Resolving tokens ----------

async function resolveVariable(entry) {
  try {
    const v = await figma.variables.getVariableByIdAsync(entry.id);
    if (v) return v;
  } catch (e) {
    console.log("Local id failed for " + entry.name + ", trying key", e);
  }
  try {
    return await figma.variables.importVariableByKeyAsync(entry.key);
  } catch (e) {
    console.error("Variable not found: " + entry.name, e);
    return null;
  }
}

async function resolveStyle(entry) {
  try {
    const s = await figma.getStyleByIdAsync(entry.id);
    if (s) return s;
  } catch (e) {
    console.log("Local id failed for style " + entry.name + ", trying key", e);
  }
  try {
    return await figma.importStyleByKeyAsync(entry.key);
  } catch (e) {
    console.error("Style not found: " + entry.name, e);
    return null;
  }
}

// The local id is only trusted if the key matches: node ids aren't global, so the
// same id can point to an unrelated node in another file.
async function resolveComponent(entry) {
  try {
    const local = await figma.getNodeByIdAsync(entry.id);
    if (local && local.key === entry.key) return entry.isSet ? local.defaultVariant : local;
  } catch (e) {
    console.log("Local id failed for component " + entry.name + ", trying key", e);
  }
  try {
    if (entry.isSet) return (await figma.importComponentSetByKeyAsync(entry.key)).defaultVariant;
    return await figma.importComponentByKeyAsync(entry.key);
  } catch (e) {
    console.error("Component not found: " + entry.name, e);
    return null;
  }
}

const RESOLVE_FN = { variable: resolveVariable, style: resolveStyle, component: resolveComponent };

// ---------- Applying ops ----------

// Auto-layout frame selected: add as last child. Anything else selected: add
// right after it as a sibling. Nothing selected, or Figma refuses (e.g. inside
// an instance): center of the viewport.
function placeNode(instance, anchor) {
  try {
    if (anchor && anchor.type !== "INSTANCE" && "layoutMode" in anchor && anchor.layoutMode !== "NONE") {
      anchor.appendChild(instance);
      return;
    }
    const parent = anchor && anchor.parent;
    if (parent && "insertChild" in parent) {
      parent.insertChild(parent.children.indexOf(anchor) + 1, instance);
      if (!("layoutMode" in parent) || parent.layoutMode === "NONE") {
        instance.x = anchor.x + anchor.width + 16;
        instance.y = anchor.y;
      }
      return;
    }
  } catch (e) {
    console.log("Could not place next to the selection, using viewport center", e);
  }
  figma.currentPage.appendChild(instance);
  instance.x = figma.viewport.center.x - instance.width / 2;
  instance.y = figma.viewport.center.y - instance.height / 2;
}

function bindFields(node, fields, variable) {
  let hit = false;
  for (const field of fields) {
    if (!(field in node)) continue;
    try {
      node.setBoundVariable(field, variable);
      hit = true;
    } catch (e) {
      console.error(field, e);
    }
  }
  return hit;
}

// Binds the color variable to the first paint of node.fills or node.strokes,
// adding a solid paint if there is none. Text with several colors (mixed fills)
// gets one fill for all of it.
function bindPaint(node, prop, variable) {
  const paints = node[prop] === figma.mixed ? [] : clone(node[prop]);
  const base = paints.length > 0 && paints[0].type === "SOLID" ? paints[0] : { type: "SOLID", color: { r: 0, g: 0, b: 0 } };
  paints[0] = figma.variables.setBoundVariableForPaint(base, "color", variable);
  node[prop] = paints;
}

// Adding auto layout to a frame with children makes it hug them, like Shift+A in
// Figma. An empty frame keeps its size, so "frame alh" doesn't collapse to 0x0.
function setAutoLayout(node, direction) {
  const adding = node.layoutMode === "NONE";
  node.layoutMode = direction;
  if (adding && node.children.length) {
    node.primaryAxisSizingMode = "AUTO";
    node.counterAxisSizingMode = "AUTO";
  }
}

// For padding or gap on a frame without auto layout: children spread out more
// sideways than downwards become a row, like Shift+A does. Otherwise a column.
function guessDirection(node) {
  const spread = (axis, size) => {
    const centers = node.children.map((c) => c[axis] + c[size] / 2);
    return Math.max(...centers) - Math.min(...centers);
  };
  return node.children.length > 1 && spread("x", "width") > spread("y", "height") ? "HORIZONTAL" : "VERTICAL";
}

// What each layer can take, for opSupports/checkOps in parse.js.
function nodeCaps(node) {
  return {
    fills: "fills" in node,
    strokes: "strokes" in node,
    radius: "cornerRadius" in node,
    corners: "topLeftRadius" in node,
    autoLayout: "layoutMode" in node && node.layoutMode !== "NONE",
    grid: "layoutMode" in node && node.layoutMode === "GRID",
    // Instances get their auto layout from the main component.
    canAutoLayout: "layoutMode" in node && node.type !== "INSTANCE",
    text: node.type === "TEXT",
  };
}

// Text styles can only be applied once their font is loaded. Throws a readable
// error if the font isn't available on this machine.
async function loadStyleFont(style) {
  try {
    await figma.loadFontAsync(style.fontName);
  } catch (e) {
    throw new Error("font " + style.fontName.family + " " + style.fontName.style + " isn't available");
  }
}

// H1-H5 get "Header H5" as their text, other styles "Text".
async function insertText(style, anchor) {
  const text = figma.createText();
  await figma.loadFontAsync(text.fontName);
  await loadStyleFont(style);
  text.characters = /^H[1-5]$/.test(style.name) ? "Header " + style.name : "Text";
  await text.setTextStyleIdAsync(style.id);
  placeNode(text, anchor);
  figma.currentPage.selection = [text];
}

// Gap auto is space-between. A gap token on such a frame switches it back to
// packed, or the token wouldn't show. Plain gap on a grid sets both grid gaps.
function applyGap(node, op, variable) {
  if (op.value === "auto") {
    node.primaryAxisAlignItems = "SPACE_BETWEEN";
    return;
  }
  if (op.side === "ALL" && node.layoutMode === "GRID") return bindFields(node, [...FIELD_SETS.gap.COL, ...FIELD_SETS.gap.ROW], variable);
  if (op.side === "ALL" && node.primaryAxisAlignItems === "SPACE_BETWEEN") node.primaryAxisAlignItems = "MIN";
  bindFields(node, FIELD_SETS.gap[op.side], variable);
}

// Returns how many layers the op touched. mode comes from checkOps: "insert"
// creates a layer (frame, component, or text when no text is selected).
async function applyOp(op, target, nodes, mode) {
  if (op.kind === "frame") {
    const frame = figma.createFrame();
    frame.name = "Frame";
    placeNode(frame, nodes[0]);
    figma.currentPage.selection = [frame];
    return 1;
  }
  if (op.kind === "component") {
    const instance = target.createInstance();
    placeNode(instance, nodes[0]);
    figma.currentPage.selection = [instance];
    return 1;
  }
  if (op.kind === "textstyle" && mode === "insert") {
    await insertText(target, nodes[0]);
    return 1;
  }
  if (op.kind === "textstyle") await loadStyleFont(target);
  let touched = 0;
  for (const node of nodes) {
    if (!opSupports(nodeCaps(node), op)) continue;
    if (op.kind === "fill") {
      bindPaint(node, "fills", target);
    } else if (op.kind === "stroke") {
      bindPaint(node, "strokes", target);
      // Borders always default to 1px on all sides, replacing per-side weights.
      if ("strokeWeight" in node) node.strokeWeight = 1;
    } else if (op.kind === "autolayout") {
      setAutoLayout(node, op.value);
    } else if (op.kind === "gap") {
      if (node.layoutMode === "NONE") setAutoLayout(node, guessDirection(node));
      applyGap(node, op, target);
    } else if (op.kind === "padding") {
      if (node.layoutMode === "NONE") setAutoLayout(node, guessDirection(node));
      bindFields(node, FIELD_SETS[op.kind][op.side], target);
    } else if (op.kind === "textstyle") {
      await node.setTextStyleIdAsync(target.id);
    } else if (op.kind === "radius" && op.side === "ALL" && !nodeCaps(node).corners) {
      // Shapes like stars and polygons only have one uniform radius
      bindFields(node, ["cornerRadius"], target);
    } else {
      bindFields(node, FIELD_SETS[op.kind][op.side], target);
    }
    touched++;
  }
  return touched;
}

async function applyOps(ops) {
  let nodes = [...figma.currentPage.selection];
  // The palette only offers ops that pass this check, but the selection may have
  // changed since. Never apply something that would partly do nothing.
  const check = checkOps(ops, nodes.map(nodeCaps));
  if (check.error) return { message: check.error, failed: true };
  const label = describeOpsIn(ops, check.modes);
  const done = slowNotice(label);
  const skipped = [];
  try {
    for (let i = 0; i < ops.length; i++) {
      const op = ops[i];
      // Word ops (frame, alh, alv) and gap auto have no token to resolve.
      let target = null;
      if (op.slug) {
        const entry = VARIABLE_MAP[op.slug];
        if (!entry) {
          skipped.push(op.label + " (no longer in the plugin)");
          continue;
        }
        target = await RESOLVE_FN[entry.type](entry);
        if (!target) {
          skipped.push(op.label + " (not in an enabled library)");
          continue;
        }
      }
      if ((await applyOp(op, target, nodes, check.modes[i])) === 0) skipped.push(op.label);
      if (check.modes[i] === "insert") nodes = [...figma.currentPage.selection];
    }
    await remember(ops, label);
  } catch (e) {
    console.error(e);
    skipped.push("error: " + e.message);
  } finally {
    done();
  }
  return { message: skipped.length ? "Skipped: " + skipped.join(", ") : "✓ " + label, failed: skipped.length === ops.length };
}

// Figma's own running indicator only shows the plugin name. Say what's
// happening, but only if it's slow (e.g. the first import from a library).
// Returns a function that ends it.
function slowNotice(label) {
  let loading = null;
  const timer = setTimeout(() => {
    loading = figma.notify(label + "…", { timeout: Infinity });
  }, 400);
  return () => {
    clearTimeout(timer);
    if (loading) loading.cancel();
  };
}

async function remember(ops, label) {
  state.recents = [{ ops, label }].concat(state.recents.filter((r) => r.label !== label)).slice(0, MAX_RECENTS);
  await figma.clientStorage.setAsync("recents", state.recents);
}

// ---------- Aliases ----------

async function setAlias(name, expansion) {
  if (expansion) state.aliases[name] = expansion;
  else delete state.aliases[name];
  await figma.clientStorage.setAsync("aliases", state.aliases);
}

// Accepts { "aliases": { "name": "expansion" }, "hidden": [slugs] } as produced by
// Copy as JSON. Valid aliases are merged in, invalid ones are reported and
// skipped. hidden replaces the current choice; unknown slugs are dropped.
async function importBackup(json) {
  let data;
  try {
    data = JSON.parse(json);
  } catch (e) {
    return "Not valid JSON";
  }
  const incoming = data && typeof data.aliases === "object" ? data.aliases : null;
  if (!incoming && !Array.isArray(data && data.hidden)) return 'Expected { "aliases": { ... }, "hidden": [ ... ] }';
  if (Array.isArray(data.hidden)) {
    state.hidden = data.hidden.filter((slug) => VARIABLE_MAP[slug]);
    await figma.clientStorage.setAsync("hidden", state.hidden);
  }
  if (!incoming) return null;
  const rejected = [];
  const respaced = respaceAliases(incoming);
  for (const name of Object.keys(respaced)) {
    const err = aliasError(ENTRIES, name, respaced[name]);
    if (err) rejected.push(name + " (" + err + ")");
    else state.aliases[name] = respaced[name];
  }
  await figma.clientStorage.setAsync("aliases", state.aliases);
  return rejected.length ? "Skipped: " + rejected.join(", ") : null;
}

// ---------- Variable review ----------

// The last scan, by group key, so fixReview gets layers and fields from here
// and the palette only sends keys.
let review = new Map();

// Padding, gap, radius, fill and stroke values in the selection (and everything
// inside it) that aren't bound to a variable, grouped by kind, value and, for
// colors, the layer's modes (the same hex can be another token in Dark) and
// role (text gets content colors).
// Returns { groups, layers, errors }. Skipped: zeros (every plain frame has them) and
// gap with space-between, which Figma shows as Auto. Inside an
// instance only its overrides count, the values changed on that instance; the
// rest comes from the main component and is fixed there.
async function scanSelection() {
  const groups = new Map();
  const errors = [];
  let layers = 0;
  // role (fills only): "text" or "shape", since text gets content colors.
  const add = (kind, value, modes, role, target) => {
    const key = [kind, value, role || "", modes ? JSON.stringify(modes) : ""].join(" ");
    if (!groups.has(key)) groups.set(key, { key, kind, value, modes, role, targets: [] });
    groups.get(key).targets.push(target);
  };
  // overrides: layer id -> overridden fields, for everything inside an instance.
  const scanNode = async (node, overrides) => {
    const counts = (field) => !overrides || (overrides.has(node.id) && overrides.get(node.id).has(field));
    const bound = node.boundVariables || {};
    const numbers = (kind, fields) => {
      for (const field of fields) {
        if (typeof node[field] === "number" && node[field] > 0 && !bound[field] && counts(field)) add(kind, node[field], null, null, { node, field });
      }
    };
    if ("layoutMode" in node && node.layoutMode !== "NONE") {
      numbers("padding", FIELD_SETS.padding.ALL);
      if (node.layoutMode === "GRID") numbers("gap", [...FIELD_SETS.gap.COL, ...FIELD_SETS.gap.ROW]);
      else if (node.primaryAxisAlignItems !== "SPACE_BETWEEN") numbers("gap", ["itemSpacing"]);
      if (node.layoutWrap === "WRAP") numbers("gap", ["counterAxisSpacing"]);
    }
    if ("topLeftRadius" in node) numbers("radius", FIELD_SETS.radius.ALL);
    else if ("cornerRadius" in node) numbers("radius", ["cornerRadius"]);
    let modes = null;
    for (const [prop, kind] of [["fills", "fill"], ["strokes", "stroke"]]) {
      if (!(prop in node) || node[prop] === figma.mixed || (prop === "strokes" && node.strokeWeight === 0) || !counts(prop)) continue;
      for (let index = 0; index < node[prop].length; index++) {
        const paint = node[prop][index];
        if (paint.type !== "SOLID" || paint.visible === false || (paint.boundVariables && paint.boundVariables.color)) continue;
        modes = modes || (await layerModes(node));
        const hex = exportValue(Object.assign({}, paint.color, { a: paint.opacity === undefined ? 1 : paint.opacity }));
        add(kind, hex, modes, kind === "fill" ? (node.type === "TEXT" ? "text" : "shape") : null, { node, prop, index });
      }
    }
  };
  // A layer that can't be read is reported and skipped, not the whole review.
  const visit = async (node, overrides) => {
    layers++;
    try {
      if (node.type === "INSTANCE") {
        overrides = new Map(overrides);
        for (const o of node.overrides || []) overrides.set(o.id, new Set([...(overrides.get(o.id) || []), ...o.overriddenFields]));
      }
      await scanNode(node, overrides);
    } catch (e) {
      console.error("Review skipped " + node.name, e);
      errors.push(node.name + ": " + e.message);
    }
    if ("children" in node) for (const child of node.children) await visit(child, overrides);
  };
  for (const node of figma.currentPage.selection) await visit(node, null);
  return { groups: [...groups.values()], layers, errors };
}

async function startReview() {
  const scan = await scanSelection();
  // Options turned off in the Options tab are never proposed, so the next
  // best token takes their place.
  const hidden = new Set(state.hidden);
  const offered = ENTRIES.filter((e) => !hidden.has(e.slug));
  for (const g of scan.groups) Object.assign(g, reviewChoices(offered, VARIABLE_VALUES, g.kind, g.value, g.modes || {}, g.role));
  review = new Map(scan.groups.map((g) => [g.key, g]));
  sentImages = new Set();
  return {
    layers: scan.layers,
    errors: scan.errors,
    groups: scan.groups.map((g) => ({
      key: g.key, kind: g.kind, value: g.value, modes: g.modes, role: g.role, match: g.match, exact: g.exact,
      layers: new Set(g.targets.map((t) => t.node.id)).size,
    })),
  };
}

// Binds every place in each group to the chosen token: [{ key, slug }].
// One undo step for the whole fix.
async function fixReview(fixes) {
  const done = slowNotice("Binding variables");
  let bound = 0;
  const skipped = [];
  try {
    for (const { key, slug } of fixes) {
      const group = review.get(key);
      const entry = VARIABLE_MAP[slug];
      if (!group || !entry) continue;
      const variable = await resolveVariable(entry);
      if (!variable) {
        skipped.push(entry.name + " (not in an enabled library)");
        continue;
      }
      for (const t of group.targets) {
        if (t.node.removed) continue;
        try {
          if (t.field) {
            t.node.setBoundVariable(t.field, variable);
          } else {
            const paints = clone(t.node[t.prop]);
            paints[t.index] = figma.variables.setBoundVariableForPaint(paints[t.index], "color", variable);
            t.node[t.prop] = paints;
          }
          bound++;
        } catch (e) {
          console.error(t.node.name, e);
        }
      }
      review.delete(key);
    }
  } finally {
    done();
  }
  figma.commitUndo();
  const message = (bound ? "✓ Bound " + bound + (bound === 1 ? " value" : " values") : "Nothing bound") + (skipped.length ? ". Skipped: " + skipped.join(", ") : "");
  return { message, failed: bound === 0 };
}

// Fix variables does what Fix all does in the palette, with no window: binds
// every proposal, the same or the nearest value.
async function runFix() {
  if (!figma.currentPage.selection.length) return closeWith({ message: "Select layers to fix", failed: true });
  const { groups, errors } = await startReview();
  const proposed = groups.filter((g) => g.match);
  const skipped = errors.length ? " · Couldn't read " + errors.length + (errors.length === 1 ? " layer" : " layers") : "";
  if (!proposed.length) return closeWith({ message: "Everything uses variables" + skipped, failed: errors.length > 0 });
  const result = await fixReview(proposed.map((g) => ({ key: g.key, slug: g.match })));
  closeWith({ message: result.message + skipped, failed: result.failed });
}

// ---------- Review preview ----------

// The focused review row is shown in the palette, not on the canvas: layers a
// plugin draws there end up in undo history (⌘Z brought them back) and are
// visible to everyone in the file. Exporting an image changes nothing. The
// plugin renders the closest layer that contains the row's places and sends
// the marks (padding bands, gap strips, radius corners, outlines) as canvas
// coordinates; the palette zooms to them and draws the marks on top.
let previewRun = 0;
// Images the palette already has, by imageId. A new scan starts over, since
// the layers may have changed.
let sentImages = new Set();

// width, height: the preview's size in the palette, to pick a sharp scale.
async function sendPreview(keys, width, height) {
  const run = ++previewRun;
  // Per layer: the fields and whether paints are involved, and its label lines.
  const places = new Map();
  for (const group of keys.map((key) => review.get(key)).filter(Boolean)) {
    const name = VARIABLE_MAP[group.match] ? VARIABLE_MAP[group.match].name : "?";
    for (const t of group.targets) {
      if (t.node.removed || !t.node.absoluteBoundingBox) continue;
      if (!places.has(t.node)) places.set(t.node, { fields: new Set(), paints: false, labels: new Set() });
      const what = places.get(t.node);
      if (t.field) what.fields.add(t.field);
      else what.paints = true;
      what.labels.add(reviewLabel(group) + " → " + name);
    }
  }
  if (!places.size) return figma.ui.postMessage({ type: "preview", keys, empty: true });
  const root = previewRoot([...places.keys()]);
  const shown = [...places.keys()].filter((n) => contains(root, n));
  const origin = root.absoluteBoundingBox;
  const focus = unionBox(shown.map((n) => n.absoluteBoundingBox));
  // Sharp at twice the zoom the palette will use (up to 4x), at most 4096 px,
  // in steps of √2 so moving between rows mostly reuses an image.
  const zoom = Math.min(width / focus.width, height / focus.height, 4);
  const wanted = Math.min(2 * zoom, 4096 / Math.max(origin.width, origin.height));
  const scale = Math.pow(2, Math.floor(Math.log2(wanted) * 2) / 2);
  const imageId = root.id + "@" + scale;
  let image = null;
  if (!sentImages.has(imageId)) {
    try {
      image = await root.exportAsync({ format: "PNG", constraint: { type: "SCALE", value: scale }, useAbsoluteBounds: true });
    } catch (e) {
      console.error("Preview export failed for " + root.name, e);
    }
    if (run !== previewRun) return;
    if (image) sentImages.add(imageId);
  }
  figma.ui.postMessage({
    type: "preview",
    keys,
    imageId: sentImages.has(imageId) ? imageId : null,
    image,
    origin: plainBox(origin),
    focus,
    marks: shown.map((n) => previewMarks(n, places.get(n))),
    elsewhere: places.size - shown.length,
  });
}

// The deepest layer that contains all of them. Layers in different top-level
// frames have only the page in common, which can't be exported: then the
// first one's top-level frame is shown, and the rest count as elsewhere.
function previewRoot(nodes) {
  for (let n = nodes[0]; n && n.type !== "PAGE"; n = n.parent) {
    if (n.parent && n.parent.type === "PAGE") return n;
    if (nodes.every((other) => contains(n, other))) return n;
  }
  return nodes[0];
}

function contains(ancestor, node) {
  for (let n = node; n; n = n.parent) if (n === ancestor) return true;
  return false;
}

const plainBox = (b) => ({ x: b.x, y: b.y, width: b.width, height: b.height });

function unionBox(boxes) {
  const x = Math.min(...boxes.map((b) => b.x));
  const y = Math.min(...boxes.map((b) => b.y));
  const right = Math.max(...boxes.map((b) => b.x + b.width));
  const bottom = Math.max(...boxes.map((b) => b.y + b.height));
  return { x, y, width: right - x, height: bottom - y };
}

const CORNERS = {
  topLeftRadius: [0, 0],
  topRightRadius: [1, 0],
  bottomLeftRadius: [0, 1],
  bottomRightRadius: [1, 1],
};

// What to draw for one layer, in canvas coordinates: tinted bands (padding,
// gap strips, radius corners), whether to outline it (colors, and gaps that
// can't be strips: grid, wrap rows, no children), and its label.
function previewMarks(node, { fields, paints, labels }) {
  const box = node.absoluteBoundingBox;
  const bands = [];
  const band = (x, y, width, height) => {
    if (width > 0 && height > 0) bands.push({ x, y, width, height });
  };
  const pad = (field) => (fields.has(field) ? node[field] : 0);
  band(box.x, box.y, box.width, pad("paddingTop"));
  band(box.x, box.y + box.height - pad("paddingBottom"), box.width, pad("paddingBottom"));
  band(box.x, box.y, pad("paddingLeft"), box.height);
  band(box.x + box.width - pad("paddingRight"), box.y, pad("paddingRight"), box.height);
  const strips = fields.has("itemSpacing") ? gapStrips(node) : [];
  for (const strip of strips) band(...strip);
  for (const [field, [right, bottom]] of Object.entries(CORNERS)) {
    if (!fields.has(field) && !fields.has("cornerRadius")) continue;
    const size = Math.min(node[field] || node.cornerRadius || 0, box.width / 2, box.height / 2);
    band(box.x + right * (box.width - size), box.y + bottom * (box.height - size), size, size);
  }
  const other = [...fields].some((f) => f === "counterAxisSpacing" || f.startsWith("grid"));
  // Fix all can put many changes on one layer; name two and count the rest.
  const lines = [...labels];
  return {
    box: plainBox(box),
    bands,
    outline: paints || other || (fields.has("itemSpacing") && !strips.length),
    label: lines.slice(0, 2).join("  ·  ") + (lines.length > 2 ? "  ·  +" + (lines.length - 2) + " more" : ""),
  };
}

// The spaces between a frame's children in the flow, as [x, y, width, height].
// A child that starts a new wrapped row has no strip before it.
function gapStrips(node) {
  const horizontal = node.layoutMode === "HORIZONTAL";
  const kids = node.children
    .filter((c) => c.visible && c.layoutPositioning !== "ABSOLUTE" && c.absoluteBoundingBox)
    .map((c) => c.absoluteBoundingBox);
  const strips = [];
  for (let i = 1; i < kids.length; i++) {
    const [a, b] = [kids[i - 1], kids[i]];
    const top = Math.min(a.y, b.y);
    const left = Math.min(a.x, b.x);
    if (horizontal && b.x > a.x + a.width) strips.push([a.x + a.width, top, b.x - a.x - a.width, Math.max(a.y + a.height, b.y + b.height) - top]);
    if (!horizontal && b.y > a.y + a.height) strips.push([left, a.y + a.height, Math.max(a.x + a.width, b.x + b.width) - left, b.y - a.y - a.height]);
  }
  return strips;
}

// ---------- Palette window ----------

// Distinct capabilities only: a selection of 500 rectangles is one entry.
async function selectionInfo() {
  const sel = figma.currentPage.selection;
  const seen = new Map();
  for (const node of sel) {
    const caps = nodeCaps(node);
    seen.set(JSON.stringify(caps), caps);
  }
  return { count: sel.length, nodes: [...seen.values()], modes: await layerModes(sel[0]) };
}

// The variable modes a layer resolves to (its own or inherited from a parent),
// by collection and mode name. Names, not ids: in a file that uses Bifrost as a
// library, the collections have other ids than in the Variables file.
const collectionCache = new Map();
async function layerModes(node) {
  const modes = {};
  if (!node) return modes;
  for (const [collectionId, modeId] of Object.entries(node.resolvedVariableModes)) {
    if (!collectionCache.has(collectionId)) collectionCache.set(collectionId, await figma.variables.getVariableCollectionByIdAsync(collectionId));
    const collection = collectionCache.get(collectionId);
    const mode = collection && collection.modes.find((m) => m.modeId === modeId);
    if (mode) modes[collection.name] = mode.name;
  }
  return modes;
}

function postState(error, notice) {
  figma.ui.postMessage({ type: "state", aliases: state.aliases, recents: state.recents, hidden: state.hidden, error: error || null, notice: notice || null });
}

async function handleMessage(msg) {
  await stateReady;
  if (msg.type === "ready") {
    figma.ui.postMessage({
      type: "init",
      entries: ENTRIES.map((e) => ({ slug: e.slug, id: e.id, kind: e.kind, name: e.name, group: e.group, value: e.value, px: e.px })),
      values: VARIABLE_VALUES,
      aliases: state.aliases,
      recents: state.recents,
      hidden: state.hidden,
      selection: await selectionInfo(),
    });
  } else if (msg.type === "apply") {
    const result = await applyOps(msg.ops);
    if (msg.keepOpen) return postState(result.failed ? result.message : null, result.failed ? null : result.message);
    closeWith(result);
  } else if (msg.type === "saveAlias") {
    const name = String(msg.name || "").trim().toLowerCase();
    const expansion = String(msg.expansion || "").trim();
    const error = aliasError(ENTRIES, name, expansion);
    if (!error) await setAlias(name, expansion);
    postState(error, error ? null : "Saved alias " + name);
  } else if (msg.type === "deleteAlias") {
    await setAlias(msg.name, "");
    postState(null, "Deleted alias " + msg.name);
  } else if (msg.type === "clearRecents") {
    state.recents = [];
    await figma.clientStorage.setAsync("recents", []);
    postState(null, "Cleared recents");
  } else if (msg.type === "setHidden") {
    // The UI already shows the change; just persist it.
    state.hidden = msg.hidden;
    await figma.clientStorage.setAsync("hidden", state.hidden);
  } else if (msg.type === "import") {
    const error = await importBackup(msg.json);
    postState(error, error ? null : "Imported");
  } else if (msg.type === "resize") {
    // The window's drag handle sends sizes while dragging and save on release.
    const width = Math.max(MIN_SIZE.width, Math.round(msg.width));
    const height = Math.max(MIN_SIZE.height, Math.round(msg.height));
    figma.ui.resize(width, height);
    if (msg.save) {
      state.size = { width, height };
      await figma.clientStorage.setAsync("size", state.size);
    }
  } else if (msg.type === "preview") {
    await sendPreview(msg.keys, msg.width, msg.height);
  } else if (msg.type === "review") {
    figma.ui.postMessage(Object.assign({ type: "review" }, await startReview()));
  } else if (msg.type === "fixReview") {
    const result = await fixReview(msg.fixes);
    figma.ui.postMessage(Object.assign({ type: "review" }, await startReview()));
    postState(result.failed ? result.message : null, result.failed ? null : result.message);
  } else if (msg.type === "vars") {
    await listVariables();
  } else if (msg.type === "close") {
    figma.closePlugin();
  }
}

function closeWith(result) {
  figma.notify(result.message, { error: result.failed });
  figma.closePlugin();
}

// Alias N runs alias N with no window, so a key bound to the menu item applies
// it directly. This is what the companion app triggers.
async function runAlias(name) {
  const found = aliasOps(ENTRIES, state.aliases, name);
  closeWith(found.error ? { message: found.error, failed: true } : await applyOps(found.ops));
}

// Opened after storage is read, so the window starts at the size it had last time.
stateReady.then(() => {
  const alias = /^alias-(\d+)$/.exec(figma.command);
  if (alias) return runAlias(alias[1]);
  if (figma.command === "fix") return runFix();
  figma.showUI(UI_HTML, Object.assign({ themeColors: true, title: "Bifrost" }, state.size));
  figma.ui.onmessage = (msg) =>
    handleMessage(msg).catch((e) => {
      console.error(e);
      postState("Error: " + e.message);
    });
  // Reading modes is async, so a quick second selection change could finish
  // first; only the latest one is sent.
  let latest = 0;
  figma.on("selectionchange", async () => {
    const n = ++latest;
    const selection = await selectionInfo();
    if (n === latest) figma.ui.postMessage({ type: "selection", selection });
  });
  // Edits (also typing a value while the review is open) arrive in bursts
  // while dragging; tell the palette once things settle.
  let changeTimer = null;
  figma.on("documentchange", () => {
    clearTimeout(changeTimer);
    changeTimer = setTimeout(() => figma.ui.postMessage({ type: "changed" }), 300);
  });
});

// ---------- Debug / export helper ----------

// A variable's raw value in one mode: "#RRGGBB" (plus alpha if not opaque),
// a number, or { alias: id } when it points to another variable. The palette
// resolves aliases with the selected layer's modes (resolveValue in parse.js).
function exportValue(value) {
  if (typeof value === "number") return value;
  if (value && value.type === "VARIABLE_ALIAS") return { alias: value.id };
  if (!value || !("r" in value)) return null;
  const hex = (n) => Math.round(n * 255).toString(16).padStart(2, "0").toUpperCase();
  return "#" + hex(value.r) + hex(value.g) + hex(value.b) + ("a" in value && value.a < 1 ? hex(value.a) : "");
}

async function listVariables() {
  const collections = await figma.variables.getLocalVariableCollectionsAsync();
  const result = [];
  for (const c of collections) {
    const defaultMode = c.modes.find((m) => m.modeId === c.defaultModeId).name;
    for (const id of c.variableIds) {
      const v = await figma.variables.getVariableByIdAsync(id);
      if (!v) continue;
      const item = { collection: c.name, name: v.name, id: v.id, key: v.key, resolvedType: v.resolvedType };
      if (v.resolvedType === "COLOR" || v.resolvedType === "FLOAT") {
        item.defaultMode = defaultMode;
        item.values = Object.fromEntries(c.modes.map((m) => [m.name, exportValue(v.valuesByMode[m.modeId])]));
      }
      result.push(item);
    }
  }
  console.log(JSON.stringify(result, null, 2));
  figma.notify("Logged " + result.length + " variables to the console");
  figma.closePlugin();
}
